<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/lifecycle/prospects.php';
function pub_gate():void{if(crm_query("SELECT state FROM nd_schema_migrations WHERE version='023_publication'")->fetchColumn()!=='applied')crm_fail(503,'Раздел публикаций ещё не установлен.');}
function pub_record(int $id,bool $lock=false):array{$p=crm_query('SELECT * FROM nd_publications WHERE id=?'.($lock?' FOR UPDATE':''),[$id])->fetch();if(!$p)crm_fail(404,'Материал не найден.');return $p;}
function pub_version(int $id):array{$v=crm_query('SELECT * FROM nd_publication_versions WHERE id=?',[$id])->fetch();if(!$v||!hash_equals($v['checksum'],hash('sha256',$v['body_json'])))crm_fail(404,'Редакция не найдена.');$v['body']=json_decode($v['body_json'],true,512,JSON_THROW_ON_ERROR);return $v;}
function pub_head(array $p):array{$id=crm_query('SELECT id FROM nd_publication_versions WHERE publication_id=? AND revision_number=?',[$p['id'],$p['head_revision']])->fetchColumn();return pub_version((int)$id);}
function pub_permission(array $p,array $v):array|false{if(!$p['order_id'])return false;$kind=$p['kind']==='portfolio'?'portfolio_permission':'review_permission';return crm_query("SELECT g.* FROM nd_publication_permissions g JOIN nd_lc_document_bindings b ON b.id=g.binding_id JOIN nd_lc_templates t ON t.id=b.template_id WHERE g.version_id=? AND g.state='GRANTED' AND b.state='AGREED' AND b.order_id=? AND t.kind=? ORDER BY g.id DESC LIMIT 1",[$v['id'],$p['order_id'],$kind])->fetch();}
function pub_live(array $p,array $v):bool{return $p['state']==='PUBLISHED'&&(int)$p['published_version_id']===(int)$v['id']&&(int)$v['publication_id']===(int)$p['id']&&(!$p['order_id']||pub_permission($p,$v)!==false);}
function pub_body(array $d):array{$title=cc_text($d,'title',190);$text=cc_text($d,'text',15000);$display=cc_text($d,'display_name',190,false);$media=$d['media']??[];if(!is_array($media)||!array_is_list($media)||count($media)>12)crm_fail(422,'До 12 файлов в точной редакции.');$out=[];foreach($media as $m){if(!is_array($m))crm_fail(422,'Проверьте медиа.');$id=cc_id($m['id']??null);$file=crm_query('SELECT id,mime,checksum FROM nd_publication_media WHERE id=?',[$id])->fetch();if(!$file)crm_fail(422,'Выберите загруженный файл.');$out[]=['id'=>$id,'mime'=>$file['mime'],'checksum'=>$file['checksum'],'caption'=>cc_text($m,'caption',1000,false)];}return ['title'=>$title,'text'=>$text,'display_name'=>$display,'media'=>$out];}
function pub_save(array $d,bool $insideTransaction=false):array{$write=function()use($d){$id=$d['id']??null;$p=$id?pub_record(cc_id($id),true):null;if($p)crm_version($d,$p);$body=pub_body($d);if(!$p){$kind=$d['kind']??'';$slug=cc_text($d,'slug',80);if(!in_array($kind,['portfolio','review'],true)||!preg_match('/^[a-z][a-z0-9-]{2,79}$/D',$slug))crm_fail(422,'Выберите тип и адрес материала.');$order=$d['order_id']??null;if($order!==null)crm_record('orders',cc_id($order),true);if($kind==='review'&&$order===null)crm_fail(422,'Отзыв относится к реальному заказу; выберите заказ.');crm_query('INSERT INTO nd_publications(kind,slug,order_id) VALUES (?,?,?)',[$kind,$slug,$order]);$p=pub_record((int)db()->lastInsertId(),true);}$n=(int)$p['head_revision']+1;$raw=lc_json($body);crm_query('INSERT INTO nd_publication_versions(publication_id,revision_number,body_json,checksum) VALUES (?,?,?,?)',[$p['id'],$n,$raw,hash('sha256',$raw)]);$vid=(int)db()->lastInsertId();crm_query("UPDATE nd_publications SET head_revision=?,state=IF(state='PUBLISHED','PUBLISHED','DRAFT'),version=version+1 WHERE id=?",[$n,$p['id']]);return ['ok'=>true,'record'=>pub_record((int)$p['id']),'head'=>pub_version($vid)];};return $insideTransaction?$write():crm_idempotent('publication/save',$d,$write);}
function pub_publish(array $d,bool $publish):array{return crm_idempotent('publication/'.($publish?'publish':'unpublish'),$d,function()use($d,$publish){$p=pub_record(cc_id($d['id']??null),true);crm_version($d,$p);if(($d['confirm']??false)!==true)crm_fail(422,'Подтвердите точную публикацию/снятие владельцем.');$v=pub_head($p);if(($d['checksum']??'')!==$v['checksum'])crm_fail(409,'Редакция изменилась. Обновите просмотр.');if($publish&&$p['order_id']&&!pub_permission($p,$v))crm_fail(409,'Нужно отдельное добровольное разрешение на точное содержание этой редакции.');if($publish&&!$p['order_id']&&($d['own_materials_confirmed']??false)!==true)crm_fail(422,'Подтвердите собственные права и отсутствие чужих клиентских материалов.');$position=$d['sort_order']??(int)$p['sort_order'];if(!is_int($position)||abs($position)>100000)crm_fail(422,'Проверьте порядок.');crm_query('UPDATE nd_publications SET state=?,published_version_id=?,sort_order=?,version=version+1 WHERE id=?',[$publish?'PUBLISHED':'UNPUBLISHED',$publish?$v['id']:null,$position,$p['id']]);$grant=$p['order_id']?pub_permission($p,$v):false;if($grant)pub_event((int)$grant['id'],['type'=>'owner','id'=>1],$publish?'PUBLISHED':'UNPUBLISHED',$v['checksum'],cc_text($d,'reason',2000));return ['ok'=>true,'record'=>pub_record((int)$p['id'])];});}
function pub_event(int $id,array $a,string $action,string $hash,string $reason):void{crm_query('INSERT INTO nd_publication_permission_events(permission_id,actor_type,actor_id,action,checksum,reason) VALUES (?,?,?,?,?,?)',[$id,$a['type'],$a['id'],$action,$hash,$reason]);}
function pub_request(array $d):array{return crm_idempotent('publication/permission/request',$d,function()use($d){$p=pub_record(cc_id($d['id']??null),true);if(!$p['order_id'])crm_fail(422,'Клиентское разрешение относится к заказу.');$v=pub_head($p);if(($d['checksum']??'')!==$v['checksum'])crm_fail(409,'Проверьте точную редакцию.');$b=lc_binding(['type'=>'owner','id'=>1],cc_id($d['binding_id']??null));$expected=$p['kind']==='portfolio'?'portfolio_permission':'review_permission';if((int)$b['order_id']!==(int)$p['order_id']||$b['kind']!==$expected||$b['state']!=='AGREED')crm_fail(409,'Нужен отдельно подписанный и проверенный документ разрешения этого заказа и типа.');$snap=json_decode($b['input_snapshot'],true);$fields=$snap['package_fields']??[];$ref=$p['kind']==='portfolio'?($fields['permission.version']??''):($fields['review.publication_terms']??'');$body=$v['body'];$expectedText=$p['kind']==='portfolio'?$body['title']."\n".$body['text']:$body['text'];$actualText=$p['kind']==='portfolio'?($fields['permission.material_list']??''):($fields['review.text']??'');if($expectedText!==$actualText||$p['kind']==='review'&&($fields['review.display_name']??'')!==$body['display_name'])crm_fail(409,'Текст и имя в отдельном подписанном разрешении отличаются от редакции публикации.');$mediaReference=lc_json($body['media']);$actualMedia=$p['kind']==='portfolio'?($fields['permission.attachment_list']??''):($fields['review.photo_reference']??'');if($body['media']&&$mediaReference!==$actualMedia)crm_fail(409,'Состав медиа и подписи должны совпадать с отдельным разрешением.');if(!str_contains($ref,$v['checksum']))crm_fail(409,'Отдельное разрешение должно указывать SHA-256 точной публикационной редакции. Подготовьте документ по этой версии.');$o=crm_record('orders',(int)$p['order_id']);$old=crm_query('SELECT id FROM nd_publication_permissions WHERE version_id=?',[$v['id']])->fetchColumn();if($old)return ['ok'=>true,'id'=>(int)$old];crm_query('INSERT INTO nd_publication_permissions(version_id,binding_id,customer_id) VALUES (?,?,?)',[$v['id'],$b['id'],$o['customer_id']]);$id=(int)db()->lastInsertId();pub_event($id,['type'=>'owner','id'=>1],'REQUESTED',$v['checksum'],'Отдельный добровольный запрос на точное содержание; отказ не влияет на заказ.');return ['ok'=>true,'id'=>$id];});}
function pub_visible_permission(array $a,array $g):void{if($a['type']==='customer'&&(int)$g['customer_id']!==$a['customer_id'])crm_fail(404,'Разрешение не найдено.');if($a['type']==='prospect'){$b=ps_binding($a['session'],(int)$g['binding_id']);if((int)$b['order_id']!==(int)$a['order_id'])crm_fail(404,'Разрешение не найдено.');}}
function pub_decide(array $a,array $d):array{return crm_atomic(function()use($a,$d){$g=crm_query('SELECT * FROM nd_publication_permissions WHERE id=? FOR UPDATE',[cc_id($d['id']??null)])->fetch();if(!$g)crm_fail(404,'Разрешение не найдено.');pub_visible_permission($a,$g);if($a['type']==='owner')crm_fail(403,'Владелец не предоставляет согласие за клиента.');$v=pub_version((int)$g['version_id']);$decision=$d['decision']??'';if(($d['checksum']??'')!==$v['checksum']||($d['confirm']??false)!==true||!in_array($decision,['GRANTED','DECLINED','REVOKED'],true))crm_fail(422,'Выберите отдельное решение по точной редакции.');if($g['state']===$decision)return ['ok'=>true,'replayed'=>true];if($decision==='REVOKED'&&$g['state']!=='GRANTED'||$decision!=='REVOKED'&&$g['state']!=='REQUESTED')crm_fail(409,'Решение уже записано.');crm_query('UPDATE nd_publication_permissions SET state=?,reason=?,decided_at=UTC_TIMESTAMP() WHERE id=?',[$decision,cc_text($d,'reason',2000,false),$g['id']]);pub_event((int)$g['id'],$a,$decision,$v['checksum'],cc_text($d,'reason',2000,false));if(in_array($decision,['REVOKED','DECLINED'],true))crm_query("UPDATE nd_publications SET state='UNPUBLISHED',published_version_id=NULL,version=version+1 WHERE id=? AND published_version_id=?",[$v['publication_id'],$v['id']]);return ['ok'=>true,'published'=>false];});}

function pub_review_submit(array $a,array $d):array{
 if(!in_array($a['type'],['customer','prospect'],true))crm_fail(403,'Отзыв передаёт заказчик.');$order=cc_id($d['order_id']??null);$o=crm_record('orders',$order);if((int)$o['customer_id']!==(int)$a['customer_id']||$a['type']==='prospect'&&$order!==(int)$a['order_id'])crm_fail(404,'Заказ не найден.');$f=crm_query('SELECT delivery_state FROM nd_lc_order_flow WHERE order_id=?',[$order])->fetchColumn();if(!in_array($f,['HANDOVER_PREPARED','HANDED_OVER'],true))crm_fail(409,'Отзыв запрашивается при завершении заказа.');if(($d['confirm_private_submission']??false)!==true)crm_fail(422,'Подтвердите приватную передачу отзыва владельцу без разрешения публикации.');
 return crm_idempotent('publication/review-submit:'.$a['type'].':'.$a['id'],$d,function()use($a,$d,$order,$o){$body=['title'=>'Отзыв о заказе '.$o['number'],'text'=>cc_text($d,'text',15000),'display_name'=>cc_text($d,'display_name',190,false),'media'=>[]];$result=pub_save($body+['kind'=>'review','slug'=>'review-'.bin2hex(random_bytes(10)),'order_id'=>$order,'request_key'=>hash('sha256','review-private:'.$a['type'].':'.$a['id'].':'.$d['request_key'])],true);$e=['publication_id'=>$result['record']['id'],'checksum'=>$result['head']['checksum'],'publication_permission'=>false];if($a['type']==='prospect')ps_event($a['id'],'prospect','private_review_submitted',$e);else lc_audit($a,'order',$order,'private_review_submitted',null,$e);return ['ok'=>true,'submitted'=>true,'published'=>false];});
}
